INSERT INTO `v1_2d071eb062d79ee89bedcbc44b0d9337e36590abc11934b624d0d62f404f7ea2` VALUES (14114, 1, "", 0.2, 14114071, "", 3, "", "", "wac_birthday_talk_smile", 105611);
INSERT INTO `v1_2d071eb062d79ee89bedcbc44b0d9337e36590abc11934b624d0d62f404f7ea2` VALUES (14114, 0, "", "", 14114072, "", 21, "", 0, "vo_wac_14114_001", "vo_wac_14114");
INSERT INTO `v1_2d071eb062d79ee89bedcbc44b0d9337e36590abc11934b624d0d62f404f7ea2` VALUES (14114, 10, 1, 0, 14114073, 0.5, 11, 0, 1, "はは、その目に封印された\n誰かさんも、うれし涙は出るんだね？\n手間暇かけて、ケーキを\n準備したかいがあったよ。", 105611);
INSERT INTO `v1_2d071eb062d79ee89bedcbc44b0d9337e36590abc11934b624d0d62f404f7ea2` VALUES (14114, "", "", "", 14114074, "", 91, "", "", "", 0);
