INSERT INTO `v1_2d071eb062d79ee89bedcbc44b0d9337e36590abc11934b624d0d62f404f7ea2` VALUES (14114, 0, "", "", 14114077, "", 21, "", 0, "vo_wac_14114_002", "vo_wac_14114");
