INSERT INTO `v1_2d071eb062d79ee89bedcbc44b0d9337e36590abc11934b624d0d62f404f7ea2` VALUES (14314, 1, "", 0.2, 14314066, "", 3, "", "", "wac_birthday_talk_doya", 104311);
INSERT INTO `v1_2d071eb062d79ee89bedcbc44b0d9337e36590abc11934b624d0d62f404f7ea2` VALUES (14314, 0, "", "", 14314067, "", 21, "", 0, "vo_wac_14314_001", "vo_wac_14314");
INSERT INTO `v1_2d071eb062d79ee89bedcbc44b0d9337e36590abc11934b624d0d62f404f7ea2` VALUES (14314, 10, 1, 0, 14314068, 0.5, 11, 0, 1, "へへ、慣れないことしちまったけど、\nあたしもちょっと手伝ったんだぜ。\nその、いちご切ったりとかさ……\nほんのちょっとだけだけどな！", 104311);
INSERT INTO `v1_2d071eb062d79ee89bedcbc44b0d9337e36590abc11934b624d0d62f404f7ea2` VALUES (14314, "", "", "", 14314069, "", 91, "", "", "", 0);
