INSERT INTO `v1_2d071eb062d79ee89bedcbc44b0d9337e36590abc11934b624d0d62f404f7ea2` VALUES (14714, 1, "", 0.2, 14714071, "", 3, "", "", "wac_birthday_talk_doya", 100911);
INSERT INTO `v1_2d071eb062d79ee89bedcbc44b0d9337e36590abc11934b624d0d62f404f7ea2` VALUES (14714, 0, "", "", 14714072, "", 21, "", 0, "vo_wac_14714_001", "vo_wac_14714");
INSERT INTO `v1_2d071eb062d79ee89bedcbc44b0d9337e36590abc11934b624d0d62f404f7ea2` VALUES (14714, 10, 1, 0, 14714073, 0.5, 11, 0, 1, "ふっ、ルカには日ごろ世話になってる\nからな！　生誕を祝うのは当然だ！\nちなみに私はローソクを立てたぞ！\n見ろ、完璧なバランスだろう！？", 100911);
INSERT INTO `v1_2d071eb062d79ee89bedcbc44b0d9337e36590abc11934b624d0d62f404f7ea2` VALUES (14714, "", "", "", 14714074, "", 91, "", "", "", 0);
