INSERT INTO `v1_2d071eb062d79ee89bedcbc44b0d9337e36590abc11934b624d0d62f404f7ea2` VALUES (14714, 1, "", 0.2, 14714076, "", 3, "", "", "wac_birthday_talk_smile", 105611);
INSERT INTO `v1_2d071eb062d79ee89bedcbc44b0d9337e36590abc11934b624d0d62f404f7ea2` VALUES (14714, 0, "", "", 14714077, "", 21, "", 0, "vo_wac_14714_002", "vo_wac_14714");
INSERT INTO `v1_2d071eb062d79ee89bedcbc44b0d9337e36590abc11934b624d0d62f404f7ea2` VALUES (14714, 10, 1, 0, 14714078, 0.5, 11, 0, 1, "ああ、たしかに、こいつはすごい。\nまるで絵の中から飛び出してきた\nみたいじゃないか……ありがとう。\n大切にいただくとするよ。", 105611);
INSERT INTO `v1_2d071eb062d79ee89bedcbc44b0d9337e36590abc11934b624d0d62f404f7ea2` VALUES (14714, "", "", "", 14714079, "", 91, "", "", "", 0);
