INSERT INTO `v1_2d071eb062d79ee89bedcbc44b0d9337e36590abc11934b624d0d62f404f7ea2` VALUES (17814, 1, "", 0.2, 17814068, "", 3, "", "", "wac_birthday_talk_normal", 104711);
INSERT INTO `v1_2d071eb062d79ee89bedcbc44b0d9337e36590abc11934b624d0d62f404f7ea2` VALUES (17814, 0, "", "", 17814069, "", 21, "", 0, "vo_wac_17814_001", "vo_wac_17814");
INSERT INTO `v1_2d071eb062d79ee89bedcbc44b0d9337e36590abc11934b624d0d62f404f7ea2` VALUES (17814, 10, 1, 0, 17814070, 0.5, 11, 0, 1, "うん、そうだよ。\n【王宮騎士団（NIGHTMARE）】\nと少年から、またひとつ成長した\nトモちゃんにプレゼントだ。", 104711);
INSERT INTO `v1_2d071eb062d79ee89bedcbc44b0d9337e36590abc11934b624d0d62f404f7ea2` VALUES (17814, "", "", "", 17814071, "", 91, "", "", "", 0);
INSERT INTO `v1_2d071eb062d79ee89bedcbc44b0d9337e36590abc11934b624d0d62f404f7ea2` VALUES (17814, 1, "", 0.2, 17814072, "", 3, "", "", "wac_birthday_idle_normal", 104711);
INSERT INTO `v1_2d071eb062d79ee89bedcbc44b0d9337e36590abc11934b624d0d62f404f7ea2` VALUES (17814, 1, "", 0.2, 17814073, "", 3, "", "", "wac_birthday_talk_smile", 100511);
INSERT INTO `v1_2d071eb062d79ee89bedcbc44b0d9337e36590abc11934b624d0d62f404f7ea2` VALUES (17814, 0, "", "", 17814074, "", 21, "", 0, "vo_wac_17814_002", "vo_wac_17814");
INSERT INTO `v1_2d071eb062d79ee89bedcbc44b0d9337e36590abc11934b624d0d62f404f7ea2` VALUES (17814, 10, 1, 0, 17814075, 0.5, 11, 0, 1, "お誕生日、おめでとうッス！\nいやー、自分も早く誕生日を迎えて、\nジュンさんやトモね～ちゃんみたいな\n大人になりたいッス！", 100511);
INSERT INTO `v1_2d071eb062d79ee89bedcbc44b0d9337e36590abc11934b624d0d62f404f7ea2` VALUES (17814, "", "", "", 17814076, "", 91, "", "", "", 0);
INSERT INTO `v1_2d071eb062d79ee89bedcbc44b0d9337e36590abc11934b624d0d62f404f7ea2` VALUES (17814, 1, "", 0.2, 17814077, "", 3, "", "", "wac_birthday_idle_smile", 100511);
INSERT INTO `v1_2d071eb062d79ee89bedcbc44b0d9337e36590abc11934b624d0d62f404f7ea2` VALUES (17814, 1, "", 0.2, 17814078, "", 3, "", "", "wac_birthday_talk_smile", 103711);
INSERT INTO `v1_2d071eb062d79ee89bedcbc44b0d9337e36590abc11934b624d0d62f404f7ea2` VALUES (17814, 0, "", "", 17814079, "", 21, "", 0, "vo_wac_17814_003", "vo_wac_17814");
INSERT INTO `v1_2d071eb062d79ee89bedcbc44b0d9337e36590abc11934b624d0d62f404f7ea2` VALUES (17814, 10, 1, 0, 17814080, 0.5, 11, 0, 1, "あはは、ありがとう。\n私は大人って呼ばれるには\n早すぎる気もするけどね。\nまだ成人すらしていないわけだし。", 103711);
INSERT INTO `v1_2d071eb062d79ee89bedcbc44b0d9337e36590abc11934b624d0d62f404f7ea2` VALUES (17814, "", "", "", 17814081, "", 91, "", "", "", 0);
INSERT INTO `v1_2d071eb062d79ee89bedcbc44b0d9337e36590abc11934b624d0d62f404f7ea2` VALUES (17814, 1, "", 0.2, 17814082, "", 3, "", "", "wac_birthday_idle_smile", 103711);
INSERT INTO `v1_2d071eb062d79ee89bedcbc44b0d9337e36590abc11934b624d0d62f404f7ea2` VALUES (17814, 1, "", 0.2, 17814083, "", 3, "", "", "wac_birthday_christina_talk_doya", 107111);
INSERT INTO `v1_2d071eb062d79ee89bedcbc44b0d9337e36590abc11934b624d0d62f404f7ea2` VALUES (17814, 0, "", "", 17814084, "", 21, "", 0, "vo_wac_17814_004", "vo_wac_17814");
INSERT INTO `v1_2d071eb062d79ee89bedcbc44b0d9337e36590abc11934b624d0d62f404f7ea2` VALUES (17814, 10, 1, 0, 17814085, 0.5, 11, 0, 1, "……なぜそこでこちらを見る？\n言っておくが、いつかオマエたち全員、\n今のワタシと同じ年齢になる日が来る。\nその時を、せいぜい震えて待つがいい。", 107111);
INSERT INTO `v1_2d071eb062d79ee89bedcbc44b0d9337e36590abc11934b624d0d62f404f7ea2` VALUES (17814, "", "", "", 17814086, "", 91, "", "", "", 0);
