INSERT INTO `v1_2d071eb062d79ee89bedcbc44b0d9337e36590abc11934b624d0d62f404f7ea2` VALUES (17814, 1, "", 0.2, 17814088, "", 3, "", "", "wac_birthday_talk_smile", 103711);
INSERT INTO `v1_2d071eb062d79ee89bedcbc44b0d9337e36590abc11934b624d0d62f404f7ea2` VALUES (17814, 0, "", "", 17814089, "", 21, "", 0, "vo_wac_17814_005", "vo_wac_17814");
INSERT INTO `v1_2d071eb062d79ee89bedcbc44b0d9337e36590abc11934b624d0d62f404f7ea2` VALUES (17814, 10, 1, 0, 17814090, 0.5, 11, 0, 1, "これはこれは、失礼いたしました♪\n……あなたも、今日はありがとう。\n記念になる日に傍にいてくれて、\n本当にうれしいよ♪", 103711);
INSERT INTO `v1_2d071eb062d79ee89bedcbc44b0d9337e36590abc11934b624d0d62f404f7ea2` VALUES (17814, "", "", "", 17814091, "", 91, "", "", "", 0);
