INSERT INTO `v1_2d071eb062d79ee89bedcbc44b0d9337e36590abc11934b624d0d62f404f7ea2` VALUES (17824, 1, "", 0.2, 17824058, "", 3, "", "", "wac_birthday_talk_smile", 106111);
INSERT INTO `v1_2d071eb062d79ee89bedcbc44b0d9337e36590abc11934b624d0d62f404f7ea2` VALUES (17824, 0, "", "", 17824059, "", 21, "", 0, "vo_wac_17824_002", "vo_wac_17824");
INSERT INTO `v1_2d071eb062d79ee89bedcbc44b0d9337e36590abc11934b624d0d62f404f7ea2` VALUES (17824, 10, 1, 0, 17824060, 0.5, 11, 0, 1, "二人とも……本当に、ありがとな！\nそれならアタシも大悪党らしく、\n豪快に、ド派手に、ワガママ放題\n楽しんでやる！", 106111);
INSERT INTO `v1_2d071eb062d79ee89bedcbc44b0d9337e36590abc11934b624d0d62f404f7ea2` VALUES (17824, "", "", "", 17824061, "", 91, "", "", "", 0);
