INSERT INTO `v1_2d071eb062d79ee89bedcbc44b0d9337e36590abc11934b624d0d62f404f7ea2` VALUES (18814, 1, "", 0.2, 18814079, "", 3, "", "", "wac_birthday_talk_wish", 105111);
INSERT INTO `v1_2d071eb062d79ee89bedcbc44b0d9337e36590abc11934b624d0d62f404f7ea2` VALUES (18814, 0, "", "", 18814080, "", 21, "", 0, "vo_wac_18814_002", "vo_wac_18814");
INSERT INTO `v1_2d071eb062d79ee89bedcbc44b0d9337e36590abc11934b624d0d62f404f7ea2` VALUES (18814, 10, 1, 0, 18814081, 0.5, 11, 0, 1, "ケーキとは別に、プレゼントも\nいくつか用意してあるのよ。\n私たちじゃどんなのがいいか\nよく分からなかったから……", 105111);
INSERT INTO `v1_2d071eb062d79ee89bedcbc44b0d9337e36590abc11934b624d0d62f404f7ea2` VALUES (18814, "", "", "", 18814082, "", 91, "", "", "", 0);
