INSERT INTO `v1_2d071eb062d79ee89bedcbc44b0d9337e36590abc11934b624d0d62f404f7ea2` VALUES (18814, 1, "", 0.2, 18814084, "", 3, "", "", "wac_birthday_talk_doya", 100911);
INSERT INTO `v1_2d071eb062d79ee89bedcbc44b0d9337e36590abc11934b624d0d62f404f7ea2` VALUES (18814, 0, "", "", 18814085, "", 21, "", 0, "vo_wac_18814_003", "vo_wac_18814");
