INSERT INTO `v1_2d071eb062d79ee89bedcbc44b0d9337e36590abc11934b624d0d62f404f7ea2` VALUES (25214, 0, "", "", 25214060, "", 21, "", 0, "vo_wac_25214_001", "vo_wac_25214");
INSERT INTO `v1_2d071eb062d79ee89bedcbc44b0d9337e36590abc11934b624d0d62f404f7ea2` VALUES (25214, 10, 1, 0, 25214061, 0.5, 11, 0, 1, "ちょっと待ってくださいお姉ちゃん！\n私たちも手伝ってますよ！\nココとか！　ココもです！", 101111);
INSERT INTO `v1_2d071eb062d79ee89bedcbc44b0d9337e36590abc11934b624d0d62f404f7ea2` VALUES (25214, "", "", "", 25214062, "", 91, "", "", "", 0);
