INSERT INTO `v1_2d071eb062d79ee89bedcbc44b0d9337e36590abc11934b624d0d62f404f7ea2` VALUES (26214, "", "", "", 26214061, "", 131, "", "", "", 1);
INSERT INTO `v1_2d071eb062d79ee89bedcbc44b0d9337e36590abc11934b624d0d62f404f7ea2` VALUES (26214, 0, "", "", 26214062, "", 21, "", 0, "vo_wac_26214_000", "vo_wac_26214");
INSERT INTO `v1_2d071eb062d79ee89bedcbc44b0d9337e36590abc11934b624d0d62f404f7ea2` VALUES (26214, 10, 1, 0, 26214063, 0.5, 11, 0, 1, "わぁ、絵本に出てきそうな\n大きなケーキですね。\nもしかして、\n私の誕生日のために……？", 103811);
INSERT INTO `v1_2d071eb062d79ee89bedcbc44b0d9337e36590abc11934b624d0d62f404f7ea2` VALUES (26214, "", "", "", 26214064, "", 91, "", "", "", 0);
