INSERT INTO `v1_2d071eb062d79ee89bedcbc44b0d9337e36590abc11934b624d0d62f404f7ea2` VALUES (26214, 1, "", 0.2, 26214066, "", 3, "", "", "wac_birthday_talk_smile", 103311);
INSERT INTO `v1_2d071eb062d79ee89bedcbc44b0d9337e36590abc11934b624d0d62f404f7ea2` VALUES (26214, 0, "", "", 26214067, "", 21, "", 0, "vo_wac_26214_001", "vo_wac_26214");
INSERT INTO `v1_2d071eb062d79ee89bedcbc44b0d9337e36590abc11934b624d0d62f404f7ea2` VALUES (26214, 10, 1, 0, 26214068, 0.5, 11, 0, 1, "そうだべ！\n誕生日おめでとう、シオシオ！\nこのケーキはシオシオの好きな\n牧場特製の食材も使って作ったべや！", 103311);
INSERT INTO `v1_2d071eb062d79ee89bedcbc44b0d9337e36590abc11934b624d0d62f404f7ea2` VALUES (26214, "", "", "", 26214069, "", 91, "", "", "", 0);
INSERT INTO `v1_2d071eb062d79ee89bedcbc44b0d9337e36590abc11934b624d0d62f404f7ea2` VALUES (26214, 1, "", 0.2, 26214070, "", 3, "", "", "wac_birthday_idle_smile", 103311);
INSERT INTO `v1_2d071eb062d79ee89bedcbc44b0d9337e36590abc11934b624d0d62f404f7ea2` VALUES (26214, 1, "", 0.2, 26214071, "", 3, "", "", "wac_birthday_talk_kyapi", 105211);
INSERT INTO `v1_2d071eb062d79ee89bedcbc44b0d9337e36590abc11934b624d0d62f404f7ea2` VALUES (26214, 0, "", "", 26214072, "", 21, "", 0, "vo_wac_26214_002", "vo_wac_26214");
INSERT INTO `v1_2d071eb062d79ee89bedcbc44b0d9337e36590abc11934b624d0d62f404f7ea2` VALUES (26214, 10, 1, 0, 26214073, 0.5, 11, 0, 1, "私もだけど、彼とリンちゃんも準備を\nがんばったのよ♪\nふふっ、シオリちゃんのために～って\n張り切ってたのよね？", 105211);
INSERT INTO `v1_2d071eb062d79ee89bedcbc44b0d9337e36590abc11934b624d0d62f404f7ea2` VALUES (26214, "", "", "", 26214074, "", 91, "", "", "", 26214073);
