INSERT INTO `v1_2d071eb062d79ee89bedcbc44b0d9337e36590abc11934b624d0d62f404f7ea2` VALUES (26214, 1, "", 0.2, 26214076, "", 3, "", "", "wac_birthday_talk_normal", 102611);
INSERT INTO `v1_2d071eb062d79ee89bedcbc44b0d9337e36590abc11934b624d0d62f404f7ea2` VALUES (26214, 0, "", "", 26214077, "", 21, "", 0, "vo_wac_26214_003", "vo_wac_26214");
INSERT INTO `v1_2d071eb062d79ee89bedcbc44b0d9337e36590abc11934b624d0d62f404f7ea2` VALUES (26214, 10, 1, 0, 26214078, 0.5, 11, 0, 1, "そ、そりゃあしおりんのためだったら、\nあたしだって、がんばるよ。\nほんと、おめでとうしおりん。\nいつもありがとね。", 102611);
INSERT INTO `v1_2d071eb062d79ee89bedcbc44b0d9337e36590abc11934b624d0d62f404f7ea2` VALUES (26214, "", "", "", 26214079, "", 91, "", "", "", 0);
