INSERT INTO `v1_2d071eb062d79ee89bedcbc44b0d9337e36590abc11934b624d0d62f404f7ea2` VALUES (26224, 1, "", 0.2, 26224066, "", 3, "", "", "wac_birthday_talk_kyapi", 101711);
INSERT INTO `v1_2d071eb062d79ee89bedcbc44b0d9337e36590abc11934b624d0d62f404f7ea2` VALUES (26224, 0, "", "", 26224067, "", 21, "", 0, "vo_wac_26224_001", "vo_wac_26224");
INSERT INTO `v1_2d071eb062d79ee89bedcbc44b0d9337e36590abc11934b624d0d62f404f7ea2` VALUES (26224, 10, 1, 0, 26224068, 0.5, 11, 0, 1, "その通り、今日はカスミの誕生日さ～♪\nさっすが名探偵だね～！\nそれじゃあ早速、みんなで歌って踊って\nお祝いするよ～♪", 101711);
INSERT INTO `v1_2d071eb062d79ee89bedcbc44b0d9337e36590abc11934b624d0d62f404f7ea2` VALUES (26224, "", "", "", 26224069, "", 91, "", "", "", 0);
