INSERT INTO `v1_2d071eb062d79ee89bedcbc44b0d9337e36590abc11934b624d0d62f404f7ea2` VALUES (27814, 1, "", 0.2, 27814076, "", 3, "", "", "wac_birthday_talk_smile", 105511);
INSERT INTO `v1_2d071eb062d79ee89bedcbc44b0d9337e36590abc11934b624d0d62f404f7ea2` VALUES (27814, 0, "", "", 27814077, "", 21, "", 0, "vo_wac_27814_002", "vo_wac_27814");
INSERT INTO `v1_2d071eb062d79ee89bedcbc44b0d9337e36590abc11934b624d0d62f404f7ea2` VALUES (27814, 10, 1, 0, 27814078, 0.5, 11, 0, 1, "お、お誕生日\nおめでとうございます、クウカさん。\nせ、せっかく、ケーキを用意したので、\nみんなでこれを食べませんか……？", 105511);
INSERT INTO `v1_2d071eb062d79ee89bedcbc44b0d9337e36590abc11934b624d0d62f404f7ea2` VALUES (27814, "", "", "", 27814079, "", 91, "", "", "", 0);
