INSERT INTO `v1_2d071eb062d79ee89bedcbc44b0d9337e36590abc11934b624d0d62f404f7ea2` VALUES (27814, 1, "", 0.2, 27814081, "", 3, "", "", "wac_birthday_talk_kyapi", 103011);
INSERT INTO `v1_2d071eb062d79ee89bedcbc44b0d9337e36590abc11934b624d0d62f404f7ea2` VALUES (27814, 0, "", "", 27814082, "", 21, "", 0, "vo_wac_27814_003", "vo_wac_27814");
INSERT INTO `v1_2d071eb062d79ee89bedcbc44b0d9337e36590abc11934b624d0d62f404f7ea2` VALUES (27814, 10, 1, 0, 27814083, 0.5, 11, 0, 1, "そうデス！\nクウカのために、\nショーグンも手伝ってくれたデスよ！\nみんなで甘いケーキを食べまショウ！", 103011);
INSERT INTO `v1_2d071eb062d79ee89bedcbc44b0d9337e36590abc11934b624d0d62f404f7ea2` VALUES (27814, "", "", "", 27814084, "", 91, "", "", "", 0);
