INSERT INTO `v1_2d071eb062d79ee89bedcbc44b0d9337e36590abc11934b624d0d62f404f7ea2` VALUES (27814, 1, "", 0.2, 27814086, "", 3, "", "", "wac_birthday_talk_smile", 100811);
INSERT INTO `v1_2d071eb062d79ee89bedcbc44b0d9337e36590abc11934b624d0d62f404f7ea2` VALUES (27814, 0, "", "", 27814087, "", 21, "", 0, "vo_wac_27814_004", "vo_wac_27814");
