INSERT INTO `v1_2d071eb062d79ee89bedcbc44b0d9337e36590abc11934b624d0d62f404f7ea2` VALUES (28414, 0, "", "", 28414072, "", 21, "", 0, "vo_wac_28414_002", "vo_wac_28414");
INSERT INTO `v1_2d071eb062d79ee89bedcbc44b0d9337e36590abc11934b624d0d62f404f7ea2` VALUES (28414, 10, 1, 0, 28414073, 0.5, 11, 0, 1, "おめでとう、マツリちゃん。\n私たちだけではなく、\n少年も一緒に準備してくれたんだよ。", 104711);
INSERT INTO `v1_2d071eb062d79ee89bedcbc44b0d9337e36590abc11934b624d0d62f404f7ea2` VALUES (28414, "", "", "", 28414074, "", 91, "", "", "", 28414073);
