INSERT INTO `v1_2d071eb062d79ee89bedcbc44b0d9337e36590abc11934b624d0d62f404f7ea2` VALUES (35314, 1, "", 0.2, 35314061, "", 3, "", "", "wac_birthday_talk_normal", 100411);
INSERT INTO `v1_2d071eb062d79ee89bedcbc44b0d9337e36590abc11934b624d0d62f404f7ea2` VALUES (35314, 0, "", "", 35314062, "", 21, "", 0, "vo_wac_35314_001", "vo_wac_35314");
INSERT INTO `v1_2d071eb062d79ee89bedcbc44b0d9337e36590abc11934b624d0d62f404f7ea2` VALUES (35314, 10, 1, 0, 35314063, 0.5, 11, 0, 1, "まじめだな～、キョウカは。\nミソギがケーキをもらったときは、\nまずどの飾りから食べようかなーって\n思ってたくらいなのに。", 100411);
INSERT INTO `v1_2d071eb062d79ee89bedcbc44b0d9337e36590abc11934b624d0d62f404f7ea2` VALUES (35314, "", "", "", 35314064, "", 91, "", "", "", 0);
