INSERT INTO `v1_2d071eb062d79ee89bedcbc44b0d9337e36590abc11934b624d0d62f404f7ea2` VALUES (35314, 1, "", 0.2, 35314066, "", 3, "", "", "wac_birthday_talk_sad", 103611);
INSERT INTO `v1_2d071eb062d79ee89bedcbc44b0d9337e36590abc11934b624d0d62f404f7ea2` VALUES (35314, 0, "", "", 35314067, "", 21, "", 0, "vo_wac_35314_002", "vo_wac_35314");
INSERT INTO `v1_2d071eb062d79ee89bedcbc44b0d9337e36590abc11934b624d0d62f404f7ea2` VALUES (35314, 10, 1, 0, 35314068, 0.5, 11, 0, 1, "でも、お返しとかあるでしょ？\nちゃんとみんなに、同じくらい\n立派なお礼を用意しないと！", 103611);
INSERT INTO `v1_2d071eb062d79ee89bedcbc44b0d9337e36590abc11934b624d0d62f404f7ea2` VALUES (35314, "", "", "", 35314069, "", 91, "", "", "", 0);
