INSERT INTO `v1_2d071eb062d79ee89bedcbc44b0d9337e36590abc11934b624d0d62f404f7ea2` VALUES (35314, 1, "", 0.2, 35314071, "", 3, "", "", "wac_birthday_talk_smile", 102011);
INSERT INTO `v1_2d071eb062d79ee89bedcbc44b0d9337e36590abc11934b624d0d62f404f7ea2` VALUES (35314, 0, "", "", 35314072, "", 21, "", 0, "vo_wac_35314_003", "vo_wac_35314");
INSERT INTO `v1_2d071eb062d79ee89bedcbc44b0d9337e36590abc11934b624d0d62f404f7ea2` VALUES (35314, 10, 1, 0, 35314073, 0.5, 11, 0, 1, "大丈夫だよ、キョウカちゃん。\nミミたちも、おにいちゃんも、\nキョウカちゃんがよろこんでくれたら、\nそれだけでうれしいよ♪", 102011);
INSERT INTO `v1_2d071eb062d79ee89bedcbc44b0d9337e36590abc11934b624d0d62f404f7ea2` VALUES (35314, "", "", "", 35314074, "", 91, "", "", "", 0);
