INSERT INTO `v1_2d071eb062d79ee89bedcbc44b0d9337e36590abc11934b624d0d62f404f7ea2` VALUES (35314, 1, "", 0.2, 35314076, "", 3, "", "", "wac_birthday_talk_wish", 103611);
INSERT INTO `v1_2d071eb062d79ee89bedcbc44b0d9337e36590abc11934b624d0d62f404f7ea2` VALUES (35314, 0, "", "", 35314077, "", 21, "", 0, "vo_wac_35314_004", "vo_wac_35314");
