INSERT INTO `v1_2d071eb062d79ee89bedcbc44b0d9337e36590abc11934b624d0d62f404f7ea2` VALUES (38014, 1, "", 0.2, 38014086, "", 3, "", "", "wac_birthday_talk_smile", 104611);
INSERT INTO `v1_2d071eb062d79ee89bedcbc44b0d9337e36590abc11934b624d0d62f404f7ea2` VALUES (38014, 0, "", "", 38014087, "", 21, "", 0, "vo_wac_38014_005", "vo_wac_38014");
INSERT INTO `v1_2d071eb062d79ee89bedcbc44b0d9337e36590abc11934b624d0d62f404f7ea2` VALUES (38014, 10, 1, 0, 38014088, 0.5, 11, 0, 1, "アキノはよく分かってるにゃ～♪\n……って、よく見たら賞味期限が\nたったの３日しかないにゃ！？\nて、手分けして食べきるにゃ～！！", 104611);
