INSERT INTO `v1_2d071eb062d79ee89bedcbc44b0d9337e36590abc11934b624d0d62f404f7ea2` VALUES (38214, "", "", "", 38214066, "", 91, "", "", "", 38214063);
INSERT INTO `v1_2d071eb062d79ee89bedcbc44b0d9337e36590abc11934b624d0d62f404f7ea2` VALUES (38214, 1, "", 0.2, 38214067, "", 3, "", "", "wac_birthday_idle_sad", 103311);
INSERT INTO `v1_2d071eb062d79ee89bedcbc44b0d9337e36590abc11934b624d0d62f404f7ea2` VALUES (38214, 1, "", 0.2, 38214068, "", 3, "", "", "wac_birthday_talk_sad", 103811);
INSERT INTO `v1_2d071eb062d79ee89bedcbc44b0d9337e36590abc11934b624d0d62f404f7ea2` VALUES (38214, 0, "", "", 38214069, "", 21, "", 0, "vo_wac_38214_001", "vo_wac_38214");
INSERT INTO `v1_2d071eb062d79ee89bedcbc44b0d9337e36590abc11934b624d0d62f404f7ea2` VALUES (38214, 10, 1, 0, 38214070, 0.5, 11, 0, 1, "マヒルさん、どうしました……？\nもしかして、誕生日ケーキに\n変なところでも……？", 103811);
INSERT INTO `v1_2d071eb062d79ee89bedcbc44b0d9337e36590abc11934b624d0d62f404f7ea2` VALUES (38214, "", "", "", 38214071, "", 91, "", "", "", 0);
