INSERT INTO `v1_2d071eb062d79ee89bedcbc44b0d9337e36590abc11934b624d0d62f404f7ea2` VALUES (38214, 1, "", 0.2, 38214078, "", 3, "", "", "wac_birthday_talk_smile", 102611);
INSERT INTO `v1_2d071eb062d79ee89bedcbc44b0d9337e36590abc11934b624d0d62f404f7ea2` VALUES (38214, 0, "", "", 38214079, "", 21, "", 0, "vo_wac_38214_003", "vo_wac_38214");
INSERT INTO `v1_2d071eb062d79ee89bedcbc44b0d9337e36590abc11934b624d0d62f404f7ea2` VALUES (38214, 10, 1, 0, 38214080, 0.5, 11, 0, 1, "いやいや、紛らわしすぎるから。\n普通のお礼で十分でしょ、\n深刻そうなオーラ醸さないでよね？", 102611);
INSERT INTO `v1_2d071eb062d79ee89bedcbc44b0d9337e36590abc11934b624d0d62f404f7ea2` VALUES (38214, "", "", "", 38214081, "", 91, "", "", "", 0);
