INSERT INTO `v1_2d071eb062d79ee89bedcbc44b0d9337e36590abc11934b624d0d62f404f7ea2` VALUES (38614, 1, "", 0.2, 38614072, "", 3, "", "", "wac_birthday_talk_normal", 105611);
INSERT INTO `v1_2d071eb062d79ee89bedcbc44b0d9337e36590abc11934b624d0d62f404f7ea2` VALUES (38614, 0, "", "", 38614073, "", 21, "", 0, "vo_wac_38614_001", "vo_wac_38614");
INSERT INTO `v1_2d071eb062d79ee89bedcbc44b0d9337e36590abc11934b624d0d62f404f7ea2` VALUES (38614, 10, 1, 0, 38614074, 0.5, 11, 0, 1, "ああ、かまわないけど……\n急にあらたまって、どうしたんだい？\nずいぶん真剣な様子じゃないか。", 105611);
INSERT INTO `v1_2d071eb062d79ee89bedcbc44b0d9337e36590abc11934b624d0d62f404f7ea2` VALUES (38614, "", "", "", 38614075, "", 91, "", "", "", 0);
INSERT INTO `v1_2d071eb062d79ee89bedcbc44b0d9337e36590abc11934b624d0d62f404f7ea2` VALUES (38614, 1, "", 0.2, 38614076, "", 3, "", "", "wac_birthday_idle_normal", 105611);
INSERT INTO `v1_2d071eb062d79ee89bedcbc44b0d9337e36590abc11934b624d0d62f404f7ea2` VALUES (38614, 1, "", 0.2, 38614077, "", 3, "", "", "wac_birthday_talk_sad", 105111);
INSERT INTO `v1_2d071eb062d79ee89bedcbc44b0d9337e36590abc11934b624d0d62f404f7ea2` VALUES (38614, 0, "", "", 38614078, "", 21, "", 0, "vo_wac_38614_002", "vo_wac_38614");
INSERT INTO `v1_2d071eb062d79ee89bedcbc44b0d9337e36590abc11934b624d0d62f404f7ea2` VALUES (38614, 10, 1, 0, 38614079, 0.5, 11, 0, 1, "いえ、あのね？\nテーブルの下に、未使用のロウソクが\n大量に袋詰めしてあるんだけど。\nこれは、なに？", 105111);
INSERT INTO `v1_2d071eb062d79ee89bedcbc44b0d9337e36590abc11934b624d0d62f404f7ea2` VALUES (38614, "", "", "", 38614080, "", 91, "", "", "", 0);
