INSERT INTO `v1_2d071eb062d79ee89bedcbc44b0d9337e36590abc11934b624d0d62f404f7ea2` VALUES (38614, 1, "", 0.2, 38614082, "", 3, "", "", "wac_birthday_talk_smile", 100911);
INSERT INTO `v1_2d071eb062d79ee89bedcbc44b0d9337e36590abc11934b624d0d62f404f7ea2` VALUES (38614, 0, "", "", 38614083, "", 21, "", 0, "vo_wac_38614_003", "vo_wac_38614");
INSERT INTO `v1_2d071eb062d79ee89bedcbc44b0d9337e36590abc11934b624d0d62f404f7ea2` VALUES (38614, 10, 1, 0, 38614084, 0.5, 11, 0, 1, "ああ、ミツキの年の数だけ\nロウソクを買ったつもりが、\nいざ実際の年齢を確認してみたら\n思ったより余ってしまって……", 100911);
INSERT INTO `v1_2d071eb062d79ee89bedcbc44b0d9337e36590abc11934b624d0d62f404f7ea2` VALUES (38614, "", "", "", 38614085, "", 91, "", "", "", 0);
