INSERT INTO `v1_2d071eb062d79ee89bedcbc44b0d9337e36590abc11934b624d0d62f404f7ea2` VALUES (38614, 1, "", 0.2, 38614087, "", 3, "", "", "wac_birthday_talk_sad", 101311);
INSERT INTO `v1_2d071eb062d79ee89bedcbc44b0d9337e36590abc11934b624d0d62f404f7ea2` VALUES (38614, 0, "", "", 38614088, "", 21, "", 0, "vo_wac_38614_004", "vo_wac_38614");
INSERT INTO `v1_2d071eb062d79ee89bedcbc44b0d9337e36590abc11934b624d0d62f404f7ea2` VALUES (38614, 10, 1, 0, 38614089, 0.5, 11, 0, 1, "ちょっ、アンナたそ、ストップ～！？\nその説明は正しいけどまずいですぞ！\n女なのに乙女心分かってなさすぎ！", 101311);
INSERT INTO `v1_2d071eb062d79ee89bedcbc44b0d9337e36590abc11934b624d0d62f404f7ea2` VALUES (38614, "", "", "", 38614090, "", 91, "", "", "", 0);
