INSERT INTO `v1_2d071eb062d79ee89bedcbc44b0d9337e36590abc11934b624d0d62f404f7ea2` VALUES (39114, 1, "", 0.2, 39114066, "", 3, "", "", "wac_birthday_talk_smile", 104611);
INSERT INTO `v1_2d071eb062d79ee89bedcbc44b0d9337e36590abc11934b624d0d62f404f7ea2` VALUES (39114, 0, "", "", 39114067, "", 21, "", 0, "vo_wac_39114_001", "vo_wac_39114");
INSERT INTO `v1_2d071eb062d79ee89bedcbc44b0d9337e36590abc11934b624d0d62f404f7ea2` VALUES (39114, 10, 1, 0, 39114068, 0.5, 11, 0, 1, "当然のことをしたまでにゃ♪\nアキノとは【メルクリウス財団】の\n仲間として、一緒に苦労してきたにゃ。", 104611);
INSERT INTO `v1_2d071eb062d79ee89bedcbc44b0d9337e36590abc11934b624d0d62f404f7ea2` VALUES (39114, "", "", "", 39114069, "", 91, "", "", "", 0);
