INSERT INTO `v1_2d071eb062d79ee89bedcbc44b0d9337e36590abc11934b624d0d62f404f7ea2` VALUES (39114, 1, "", 0.2, 39114071, "", 3, "", "", "wac_birthday_talk_normal", 104811);
INSERT INTO `v1_2d071eb062d79ee89bedcbc44b0d9337e36590abc11934b624d0d62f404f7ea2` VALUES (39114, 0, "", "", 39114072, "", 21, "", 0, "vo_wac_39114_002", "vo_wac_39114");
INSERT INTO `v1_2d071eb062d79ee89bedcbc44b0d9337e36590abc11934b624d0d62f404f7ea2` VALUES (39114, 10, 1, 0, 39114073, 0.5, 11, 0, 1, "いろんなことがあったわよね……\n飛空艇を沈め、学院を破壊し、\n何度も破産の危機を迎えながらも……", 104811);
INSERT INTO `v1_2d071eb062d79ee89bedcbc44b0d9337e36590abc11934b624d0d62f404f7ea2` VALUES (39114, "", "", "", 39114074, "", 91, "", "", "", 0);
