INSERT INTO `v1_2d071eb062d79ee89bedcbc44b0d9337e36590abc11934b624d0d62f404f7ea2` VALUES (39114, 0, "", "", 39114077, "", 21, "", 0, "vo_wac_39114_003", "vo_wac_39114");
INSERT INTO `v1_2d071eb062d79ee89bedcbc44b0d9337e36590abc11934b624d0d62f404f7ea2` VALUES (39114, 10, 1, 0, 39114078, 0.5, 11, 0, 1, "麦しゅわの助けも借りながら、\nみんなで協力して、\n全部乗り越えることができたもの！", 103411);
INSERT INTO `v1_2d071eb062d79ee89bedcbc44b0d9337e36590abc11934b624d0d62f404f7ea2` VALUES (39114, "", "", "", 39114079, "", 91, "", "", "", 0);
